export function OnPageSeoContent({ page, language }: { page: SeoPage; language: Language }) {
  const ui = copies[page][language];
  return <section className="mx-auto mt-12 max-w-5xl space-y-10 border-t border-[#1e293b] pt-10" aria-labelledby={`${page}-seo-title`}>
    <div className="max-w-3xl"><span className="text-xs font-semibold text-emerald-400">{ui.eyebrow}</span><h2 id={`${page}-seo-title`} className="mt-2 text-2xl font-extrabold text-white sm:text-3xl">{ui.title}</h2><p className="mt-3 text-sm leading-7 text-slate-400">{ui.intro}</p></div>
    <div className="space-y-9">{ui.sections.map(section => <article key={section.title}><h2 className="text-xl font-bold text-white">{section.title}</h2>{section.paragraphs.map(paragraph => <p key={paragraph} className="mt-3 text-sm leading-7 text-slate-400">{paragraph}</p>)}{section.bullets && <ul className="mt-3 list-disc space-y-2 pl-5 text-sm leading-7 text-slate-400">{section.bullets.map(item => <li key={item}>{item}</li>)}</ul>}</article>)}</div>
    <section aria-labelledby={`${page}-faq-title`}><h2 id={`${page}-faq-title`} className="text-xl font-bold text-white">{ui.faqTitle}</h2><div className="mt-4 grid gap-3 md:grid-cols-2">{ui.faqs.map(([question, answer]) => <details key={question} className="rounded-xl border border-[#1e293b] bg-[#0f1722] p-4"><summary className="cursor-pointer text-sm font-semibold text-slate-200">{question}</summary><p className="mt-2 text-sm leading-6 text-slate-400">{answer}</p></details>)}</div></section>
    <nav aria-label={ui.relatedTitle} className="flex flex-wrap gap-x-5 gap-y-3 border-t border-[#1e293b] pt-6 text-sm text-emerald-300">{ui.related.map(([label, path]) => <a key={path} href={href(path, language)} className="hover:text-emerald-200">{label}</a>)}</nav>
  </section>;
}

